package validation

import "fyne.io/fyne/v2"

// NewAllStrings creates a validator that runs all provided validators in sequence.
// It returns the first error encountered, or nil if all validators pass.
// This enables chaining multiple validators together (e.g., time format + regexp).
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	if len(validators) == 0 {
		return func(string) error {
			return nil
		}
	}

	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}

package desktop

import "fyne.io/fyne/v2"

// Lifecycle represents an app that can respond to system events.
//
// Since: 2.2
type Lifecycle interface {
	// OnResume is called when the app returns from being hidden or inactive.
	OnResume()

	// OnSuspend is called when the app is hidden or made inactive.
	OnSuspend()
}

// SystemTrayApp defines an application that supports system tray functionality.
// Apps can use this to provide quick access to actions when minimized.
//
// Since: 2.2
type SystemTrayApp interface {
	// SetSystemTrayMenu sets the menu that appears when the system tray icon is activated.
	SetSystemTrayMenu(*fyne.Menu)

	// SetSystemTrayIcon sets the icon displayed in the system tray.
	// If not set, the app icon will be used.
	SetSystemTrayIcon(fyne.Resource)
}

// ShortcutHandler is an interface for apps that want to handle keyboard shortcuts
// at the application level, before they reach individual windows or widgets.
//
// Since: 2.2
type ShortcutHandler interface {
	// TypedShortcut handles application-level shortcuts.
	// Return true if the shortcut was handled, false to pass it to windows.
	TypedShortcut(fyne.Shortcut) bool
}

